```js
function debounce(fn, delay) {
  let timerId;

  return function (...args) {
    const context = this;

    clearTimeout(timerId);

    timerId = setTimeout(() => {
      fn.apply(context, args);
    }, delay);
  };
}
```

### Example
```js
const onResize = debounce(() => {
  console.log("Resized!");
}, 300);

window.addEventListener("resize", onResize);
```

### How it works
- Each call resets the timer.
- `fn` is only executed after `delay` ms pass without another call.
- `apply` preserves `this` and forwards arguments.

```js
function debounce(fn, delay) {
  let timer;
  return function (...args) {
    clearTimeout(timer);
    timer = setTimeout(() => fn.apply(this, args), delay);
  };
}
```

