Here’s a simple React countdown timer component that counts down from a given number of seconds.

### `CountdownTimer.jsx`
```jsx
import React, { useEffect, useState } from "react";

function CountdownTimer({ initialSeconds = 60 }) {
  const [secondsLeft, setSecondsLeft] = useState(initialSeconds);
  const [isRunning, setIsRunning] = useState(true);

  useEffect(() => {
    if (!isRunning || secondsLeft <= 0) return;

    const timerId = setInterval(() => {
      setSecondsLeft((prev) => {
        if (prev <= 1) {
          clearInterval(timerId);
          setIsRunning(false);
          return 0;
        }
        return prev - 1;
      });
    }, 1000);

    return () => clearInterval(timerId);
  }, [isRunning, secondsLeft]);

  const formatTime = (totalSeconds) => {
    const minutes = Math.floor(totalSeconds / 60);
    const seconds = totalSeconds % 60;
    return `${String(minutes).padStart(2, "0")}:${String(seconds).padStart(2, "0")}`;
  };

  return (
    <div style={{ fontFamily: "sans-serif", textAlign: "center" }}>
      <h2>Countdown Timer</h2>
      <div style={{ fontSize: "2rem", marginBottom: "1rem" }}>
        {formatTime(secondsLeft)}
      </div>
      <button onClick={() => setIsRunning((r) => !r)} style={{ marginRight: "0.5rem" }}>
        {isRunning ? "Pause" : "Resume"}
      </button>
      <button
        onClick={() => {
          setSecondsLeft(initialSeconds);
          setIsRunning(true);
        }}
      >
        Reset
      </button>
    </div>
  );
}

export default CountdownTimer;
```

### Usage
```jsx
import React from "react";
import CountdownTimer from "./CountdownTimer";

function App() {
  return (
    <div>
      <CountdownTimer initialSeconds={90} />
    </div>
  );
}

export default App;
```

### Notes
- `initialSeconds` controls the starting value.
- It includes **pause/resume** and **reset**.
- Time is displayed as `MM:SS`.

